SourceCode.Declaration:
class METDebugBatchJob extends RunBase
{
    RecId jobId;
    NoYesId   doTTSBegin;
    NoYesId   doTTSCommit;
    Batch batch;

    DialogField dfJobId;
    DialogField dfTTSBegin;
    DialogField dfTTSCommit;

}

Method.Source:
public Object dialog()
{
    Dialog dialog = super();

    dfJobId     = dialog.addFieldValue(extendedTypeStr(RecId), jobId, "Batch Job Id");
    dfTTSBegin  = dialog.addFieldValue(enumStr(NoYes), doTTSBegin, "Use ttsBegin");
    dfTTSCommit = dialog.addFieldValue(enumStr(NoYes), doTTSCommit, "Use ttsCommit");

    return dialog;
}

public boolean getFromDialog()
{
    boolean ret = super();

    jobId       = dfJobId.value();
    doTTSBegin  = dfTTSBegin.value();
    doTTSCommit = dfTTSCommit.value();

    return ret;
}

public void run()
{
    if (!jobId)
    {
        throw error("Batch Job Id is required");
    }

    try
    {
        if (doTTSBegin == NoYes::Yes)
        {
            ttsbegin;
        }

        info(strFmt("Executing batch job: %1", jobId));

        select firstonly batch
            where batch.BatchJobId == jobId;

        if (batch)
        {
            changecompany(batch.Company)
            {
                BatchRun::runJobStatic(jobId);

                info("Batch job execution completed");
            }
        }

        if (doTTSBegin == NoYes::Yes)
        {
            if (doTTSCommit == NoYes::Yes)
            {
                ttscommit;
                info("Transaction committed");
            }
            else
            {
                ttsabort;
                info("Transaction aborted");
            }
        }
    }
    catch (Exception::Error)
    {
        if (appl.ttsLevel() > 0)
        {
            ttsabort;
        }

        error("Error while executing batch job");
    }
}

/// <summary>
/// Class entry point. The system will call this method when a designated menu
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METDebugBatchJob obj = new METDebugBatchJob();

    if (obj.prompt())
    {
        obj.run();
    }
}
